+ * frame follows straight after the boosted one. */
+static uint16_t *odPx, *prevPx;
+static bool isLit(uint16_t canvasPx) {
+  const uint16_t v = px_swap(canvasPx);
+  const int r = ((v >> 11) & 31) << 3, g = ((v >> 5) & 63) << 2, b = (v & 31) << 3;
+  return 77 * r + 151 * g + 28 * b > 40 * 256;
+}
+static uint16_t boosted(uint16_t canvasPx) {
+  const uint16_t v = px_swap(canvasPx);
+  int r = (v >> 11) & 31, g = (v >> 5) & 63, b = v & 31;
+  r = r * OVERDRIVE_GAIN_PCT / 100;
+  g = g * OVERDRIVE_GAIN_PCT / 100;
+  b = b * OVERDRIVE_GAIN_PCT / 100;
+  if (r > 31) r = 31;
+  if (g > 63) g = 63;
+  if (b > 31) b = 31;
+  return px_swap((uint16_t)((r << 11) | (g << 5) | b));
+}
