import sys, numpy as np
S, RAW, cx, cy = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4])
a = np.fromfile(f"{S}/{RAW}", np.uint8).reshape(-1, 540, 960)
print("frames", len(a))
def shift(ref, cur):
    w = np.outer(np.hanning(ref.shape[0]), np.hanning(ref.shape[1]))
    F = np.fft.fft2(ref * w) * np.conj(np.fft.fft2(cur * w))
    r = np.fft.ifft2(F / (np.abs(F) + 1e-6)).real
    y, x = np.unravel_index(r.argmax(), r.shape); h, wd = r.shape
    return (y if y < h // 2 else y - h, x if x < wd // 2 else x - wd)
for n, (y0, y1, x0, x1) in {"B": (500, 540, 300, 700), "T": (0, 30, 400, 640), "TL": (0, 120, 300, 420)}.items():
    ref = a[0, y0:y1, x0:x1].astype(np.float32)
    sh = np.array([shift(ref, a[i, y0:y1, x0:x1].astype(np.float32)) for i in range(0, len(a), 20)])
    print(n, "dy", sh[:, 0].min(), sh[:, 0].max(), "dx", sh[:, 1].min(), sh[:, 1].max())
h, nb = 168, 12
roi = a[:, cy - h:cy + h, cx - h:cx + h].astype(np.float32)
whole = roi.mean(axis=(1, 2)); whole /= np.median(whole)
rowb = roi.reshape(len(a), nb, 2 * h // nb, 2 * h).mean(axis=(2, 3))
colb = roi.reshape(len(a), 2 * h, nb, 2 * h // nb).mean(axis=(1, 3))
t = np.arange(len(whole)); NB = 20
def fold(s, P):
    k = ((t % P) / P * NB).astype(int)
    return np.bincount(k, weights=s, minlength=NB) / np.maximum(np.bincount(k, minlength=NB), 1)
d, P = max((np.median(fold(whole, P)) - fold(whole, P).min(), P) for P in np.arange(22.0, 30.0, 0.01))
prof = fold(whole, P)
print("push period %.2f frames (%.2f Hz); folded whole dip %.3f" % (P, 120 / P, prof.min() / np.median(prof)))
ph0 = (np.argmin(prof) + 0.5) / NB * P
ev = []; n = 0
while True:
    c = ph0 + n * P; n += 1
    if c < 10: continue
    if c > len(whole) - 30: break
    lo = int(c) - 4; ev.append(lo + int(whole[lo:lo + 9].argmin()))
def stat(ser, idx): return [(ser[i - 2:i + 5] / ser[i + 10:i + 20].mean(axis=0)).min() for i in idx]
r, c_, w = stat(rowb, ev), stat(colb, ev), [whole[i] / whole[i + 10:i + 20].mean() for i in ev]
print("events %d | dimmest row band: mean %.3f min %.3f max %.3f | col band: mean %.3f min %.3f max %.3f | whole at dip %.3f" % (len(ev), np.mean(r), min(r), max(r), np.mean(c_), min(c_), max(c_), np.mean(w)))
ev2 = [e + int(P / 2) for e in ev if e + int(P / 2) + 20 < len(a)]
nr, nc = stat(rowb, ev2), stat(colb, ev2)
