"""Is the per-push dip a uniform dimming of every line in the band, or a
one-line event (a seam)? Compares the dip frame with the settled frame, row by
row, inside the display, for each push event found the analyse11 way."""
import sys
import numpy as np

S, RAW = sys.argv[1], sys.argv[2]
CX, CY = (int(sys.argv[3]), int(sys.argv[4])) if len(sys.argv) > 4 else (None, None)
import os
SH = (540, 960) if os.environ.get("SHAPE") == "landscape" else (960, 540)
a = np.fromfile(f"{S}/{RAW}", np.uint8).reshape(-1, *SH)
n = len(a)
sub = a[::5].astype(np.float32)
sd = sub.std(axis=0)
ys, xs = np.where(sd > np.percentile(sd, 97))
cy, cx = (CY, CX) if CX else (int(np.median(ys)), int(np.median(xs)))
print(f"frames {n}  centre guess cx={cx} cy={cy}")
h, nb = 168, 12
roi = a[:, cy - h:cy + h, cx - h:cx + h].astype(np.float32)
